from itertools import combinations

def has_triangle(edges_set, n):
    """Check if graph has a triangle."""
    adj = [[False]*n for _ in range(n)]
    for u, v in edges_set:
        adj[u][v] = True
        adj[v][u] = True
    for u, v, w in combinations(range(n), 3):
        if adj[u][v] and adj[v][w] and adj[u][w]:
            return True, (u, v, w)
    return False, None

def is_triangle_free(edges_set, n):
    result, _ = has_triangle(edges_set, n)
    return not result

def adding_edge_creates_triangle(edges_set, u, v, n):
    """Check if adding edge (u,v) creates a triangle."""
    adj = [[False]*n for _ in range(n)]
    for a, b in edges_set:
        adj[a][b] = True
        adj[b][a] = True
    # Adding (u,v): triangle if there's w such that adj[u][w] and adj[v][w]
    for w in range(n):
        if w != u and w != v:
            if adj[u][w] and adj[v][w]:
                return True
    return False

def is_maximal_triangle_free(edges_set, n):
    """Check if graph is maximal triangle-free."""
    if not is_triangle_free(edges_set, n):
        return False
    all_possible = [(u,v) for u,v in combinations(range(n), 2) if (u,v) not in edges_set]
    for u, v in all_possible:
        if not adding_edge_creates_triangle(edges_set, u, v, n):
            return False  # Can add this edge without triangle => not maximal
    return True

# Use backtracking search
n = 7
all_edges = [(u,v) for u,v in combinations(range(n), 2)]
fixed_present = {(0,6), (1,5)}

def solve():
    # Start with fixed edges
    current_edges = set(fixed_present)

    # Check fixed edges don't form triangle
    if not is_triangle_free(current_edges, n):
        return None

    # Try to build maximal triangle-free graph using backtracking
    remaining = [e for e in all_edges if e not in fixed_present]

    def backtrack(idx, edges):
        if idx == len(remaining):
            if is_maximal_triangle_free(edges, n):
                return set(edges)
            return None

        e = remaining[idx]
        u, v = e

        # Try adding edge e
        new_edges = edges | {e}
        if is_triangle_free(new_edges, n):
            result = backtrack(idx+1, new_edges)
            if result is not None:
                return result

        # Try not adding edge e
        result = backtrack(idx+1, edges)
        if result is not None:
            return result

        return None

    return backtrack(0, current_edges)

solution = solve()
if solution:
    print("Found solution:", sorted(solution))
    print("Is maximal triangle-free:", is_maximal_triangle_free(solution, n))
else:
    print("No solution found")
